-- Narrow the local manifest generated by the first 348 application: the DVT
-- sink workbench section is orchestrated from CanvasInspectorAuthoringSection
-- and must not require touching DvtAuthoringFields for this surface-strategy
-- slice.

with target_rails as (
  select rail.*
  from planning_query_store.feature_mechanization_local_rails rail
  where (
      rail.feature_id = 'E-CANVAS-SURFACE-STRATEGY-DBT-DVT-1'
      and rail.normalized_rail_name = 'resolvecanvassurfacestrategy'
    )
    or (
      rail.feature_id = 'CANVAS-NODE-CONTEXT-PROPERTIES-PANEL-20260604'
      and rail.normalized_rail_name = 'inspectcanvasnodeproperties'
    )
),
forbidden_refs as (
  select jsonb_build_array(
    'apps/web/src/app/views/canvas/DvtAuthoringFields.tsx',
    'apps/web/src/app/views/canvas/DvtAuthoringFields.tsx#DvtAuthoringFields'
  ) as values
),
symbol_patch as (
  select jsonb_build_array(
    jsonb_build_object(
      'name', 'CanvasNodeWorkbenchSectionPolicyId',
      'path', 'apps/web/src/app/plugins/canvasSurfaceStrategyContracts.ts',
      'dddOwner', 'web.component.canvas.CanvasSurfaceStrategy',
      'cqRails', jsonb_build_array('ResolveCanvasSurfaceStrategy'),
      'fowlerSignals', jsonb_build_array('published_language', 'value_object'),
      'architectureGuard', 'pnpm docs:feature-mechanization:implementation',
      'cypressCoverage', 'not_applicable: type-level strategy vocabulary',
      'unitTests', jsonb_build_array('apps/web/src/app/views/canvas/canvasNodeWorkbenchSectionStrategy.test.ts')
    ),
    jsonb_build_object(
      'name', 'buildSinkRows',
      'path', 'apps/web/src/app/components/inspector/nodePropertiesReadModel.ts',
      'dddOwner', 'web.component.canvas.NodeWorkbench',
      'cqRails', jsonb_build_array('InspectCanvasNodeProperties'),
      'fowlerSignals', jsonb_build_array('read_model', 'extract_function'),
      'architectureGuard', 'pnpm docs:feature-mechanization:implementation',
      'cypressCoverage', 'not_applicable: passive read-model projection',
      'unitTests', jsonb_build_array('apps/web/src/app/components/inspector/nodePropertiesReadModel.test.ts')
    ),
    jsonb_build_object(
      'name', 'DVT_SINK_NODE',
      'path', 'apps/web/src/app/views/canvas/CanvasNodeWorkbenchPanel.test.tsx',
      'dddOwner', 'web.component.canvas.NodeWorkbench',
      'cqRails', jsonb_build_array('InspectCanvasNodeProperties'),
      'fowlerSignals', jsonb_build_array('test_fixture'),
      'architectureGuard', 'pnpm --filter @dvt/web exec vitest run --config vitest.canvas-presentation.config.ts src/app/views/canvas/CanvasNodeWorkbenchPanel.test.tsx',
      'cypressCoverage', 'not_applicable: component presentation proof',
      'unitTests', jsonb_build_array('apps/web/src/app/views/canvas/CanvasNodeWorkbenchPanel.test.tsx')
    )
  ) as symbols
),
filtered as (
  select
    target_rails.rail_id,
    (
      select coalesce(jsonb_agg(value order by value), '[]'::jsonb)
      from jsonb_array_elements_text(
        case
          when jsonb_typeof(coalesce(target_rails.allowed_implementation_surfaces, '[]'::jsonb)) = 'array'
            then coalesce(target_rails.allowed_implementation_surfaces, '[]'::jsonb)
          else '[]'::jsonb
        end
      ) refs(value)
      where not exists (
        select 1
        from jsonb_array_elements_text(forbidden_refs.values) forbidden(value)
        where forbidden.value = refs.value
      )
    ) as allowed_surfaces,
    (
      select coalesce(jsonb_agg(value order by value), '[]'::jsonb)
      from jsonb_array_elements_text(
        case
          when jsonb_typeof(coalesce(target_rails.symbol_refs, '[]'::jsonb)) = 'array'
            then coalesce(target_rails.symbol_refs, '[]'::jsonb)
          else '[]'::jsonb
        end
      ) refs(value)
      where not exists (
        select 1
        from jsonb_array_elements_text(forbidden_refs.values) forbidden(value)
        where forbidden.value = refs.value
      )
    ) as symbol_refs,
    (
      select coalesce(jsonb_agg(value order by value), '[]'::jsonb)
      from jsonb_array_elements_text(
        case
          when jsonb_typeof(coalesce(target_rails.implementation_refs, '[]'::jsonb)) = 'array'
            then coalesce(target_rails.implementation_refs, '[]'::jsonb)
          else '[]'::jsonb
        end
      ) refs(value)
      where not exists (
        select 1
        from jsonb_array_elements_text(forbidden_refs.values) forbidden(value)
        where forbidden.value = refs.value
      )
    ) as implementation_refs,
    (
      select coalesce(jsonb_agg(symbol order by symbol->>'path', symbol->>'name'), '[]'::jsonb)
      from (
        select distinct on (symbol->>'path', symbol->>'name') symbol
        from (
          select symbol
          from jsonb_array_elements(
            case
              when jsonb_typeof(coalesce(target_rails.raw_manifest->'symbols', '[]'::jsonb)) = 'array'
                then coalesce(target_rails.raw_manifest->'symbols', '[]'::jsonb)
              else '[]'::jsonb
            end
          ) current_symbols(symbol)
          union all
          select symbol
          from jsonb_array_elements(symbol_patch.symbols) patch_symbols(symbol)
        ) all_symbols
        where not exists (
          select 1
          from jsonb_array_elements_text(forbidden_refs.values) forbidden(value)
          where forbidden.value = concat(symbol->>'path', '#', symbol->>'name')
             or forbidden.value = symbol->>'path'
        )
        order by symbol->>'path', symbol->>'name'
      ) deduped
    ) as symbols
  from target_rails
  cross join forbidden_refs
  cross join symbol_patch
)
update planning_query_store.feature_mechanization_local_rails rail
set
  allowed_implementation_surfaces = filtered.allowed_surfaces,
  symbol_refs = filtered.symbol_refs,
  implementation_refs = filtered.implementation_refs,
  raw_manifest = jsonb_set(
    jsonb_set(
      jsonb_set(
        jsonb_set(
          coalesce(rail.raw_manifest, '{}'::jsonb),
          '{allowedImplementationSurfaces}',
          filtered.allowed_surfaces,
          true
        ),
        '{implementationRefs}',
        filtered.implementation_refs,
        true
      ),
      '{symbolRefs}',
      filtered.symbol_refs,
      true
    ),
    '{symbols}',
    filtered.symbols,
    true
  ),
  source_path = 'tools/planning-db/migrations/349_narrow_canvas_sink_workbench_section_manifest.sql',
  source_content_sha256 = md5('CANVAS-SURFACE-STRATEGY-SINK-WORKBENCH-SECTION-20260627:349:' || rail.rail_id::text),
  revision = rail.revision + 1,
  updated_at = now()
from filtered
where rail.rail_id = filtered.rail_id;
